def dihedral(sh):
 pts=list(sh); forms=[]
 for k in range(4):
  for flip in [False,True]:
   t=[]
   for r,c in pts:
    if flip:c=-c
    for _ in range(k):r,c=c,-r
    t.append((r,c))
   mr=min(r for r,c in t);mc=min(c for r,c in t)
   forms.append(tuple(sorted((r-mr,c-mc) for r,c in t)))
 return forms
